import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {randomUUID} from 'node:crypto';import pg from 'pg';
import {fixtureInput,composer} from './rankedPublicationFixture.mjs';
import {sealPublisherConfiguration,PUBLISHER_CONFIGURATION,registerLocalPublisherConfiguration,createPublisherLedger,PUBLISHER_FREEZE} from '../../durableObserve/publicationScheduler.mjs';
import {cycleV2} from '../../../shared/oceanPublication.mjs';
export async function database(){const root=path.join(process.env.LOCALAPPDATA,'Pelora/PostgreSQL/pelora_phase3_qualification'),read=n=>JSON.parse(fs.readFileSync(path.join(root,n),'utf8'));const admin=read('credentials.json'),worker=read('worker-credentials.json');for(const c of [admin,worker])assert(c.host==='127.0.0.1'&&Number(c.port)===55432&&c.cluster==='pelora_phase3_qualification');const config=c=>({host:c.host,port:c.port,user:c.username,password:c.password,database:'pelora_phase3_qualification'}),owner=new pg.Client(config(admin)),pool=new pg.Pool({...config(worker),max:6,query_timeout:10000});pool.on('error',()=>{});await owner.connect();return {registered:new Set(),owner,pool,query:(...args)=>pool.query(...args),close:async()=>{await pool.end();await owner.end();}};}
export function configuration(states=[{adequate:true,positive:true}],options={}){const now=new Date().toISOString(),date=new Date(now);date.setUTCHours(Math.floor(date.getUTCHours()/4)*4,0,0,0);const at=options.at??date.toISOString(),input=fixtureInput(states,at,'cp09-controlled-'+randomUUID());const settings={catchUpCycles:2,maxConcurrent:1,maxAttempts:3,deadlineMs:172800000,leaseMs:20000,pollMs:1000,executionTimeoutMs:10000,lookBackMs:20*86400000,...options.settings};const body={contractVersion:PUBLISHER_CONFIGURATION,context:input.context,cycleConfiguration:input.cycle.configuration,candidates:input.candidates,scopes:[],approvedAt:new Date(Date.parse(at)-14400000).toISOString(),effectiveAt:at,clockMode:'CONTROLLED_FIXTURE',settings,adapterVersion:'controlled-upstream-fixture-v1',requireHistoricalReceipt:false,...options.body};const c=sealPublisherConfiguration(body);return {c,input,now,at};}
export async function setup(db,states,options){const h=configuration(states,options);await registerLocalPublisherConfiguration(db.owner,h.c);db.registered.add(h.c.id);const ledger=createPublisherLedger({query:db.query});await ledger.enumerate(h.c,h.now);const [id]=await ledger.pending(h.c);return {...h,ledger,id,cap:randomUUID()};}
export function runtime(h,{ledger=h.ledger,collect,compose:composeOverride,...other}={}){return {ledger:{...ledger,configurations:async()=>[h.c]},collect:collect??(async(c,at)=>{const x=structuredClone(h.input);x.cycle.scheduledAt=at;return x;}),compose:composeOverride??(async(input)=> (await composer(input.artifacts[0]?.reference??h.input.artifacts[0].reference)).compose(input)),...other};}
export async function stage(h){const claim=await h.ledger.claim(h.id,h.cap),input=h.input,freeze={contractVersion:PUBLISHER_FREEZE,configurationId:h.c.id,cycleId:cycleV2(input.cycle).cycleId,constructedAt:new Date().toISOString(),input};await h.ledger.freeze(h.id,h.cap,claim.fence,freeze);const p=await (await composer(input.artifacts[0].reference)).compose(input);await h.ledger.prepare(h.id,h.cap,claim.fence,p);return {claim,p,freeze};}
